#!/usr/bin/env python3

import psutil
import json

def get_network_interfaces():
    """Get information about all network interfaces"""
    try:
        # Get network interface information
        interfaces = psutil.net_if_addrs()
        interface_stats = psutil.net_if_stats()

        network_info = {}

        for interface_name, addresses in interfaces.items():
            network_info[interface_name] = {
                'addresses': [],
                'status': 'unknown'
            }

            # Add address information
            for addr in addresses:
                addr_info = {
                    'family': str(addr.family),
                    'address': addr.address,
                    'netmask': addr.netmask,
                    'broadcast': addr.broadcast,
                    'ptp': addr.ptp
                }
                network_info[interface_name]['addresses'].append(addr_info)

            # Add status information
            if interface_name in interface_stats:
                stats = interface_stats[interface_name]
                network_info[interface_name]['status'] = 'up' if stats.isup else 'down'
                network_info[interface_name]['speed'] = stats.speed
                network_info[interface_name]['duplex'] = str(stats.duplex)
                network_info[interface_name]['mtu'] = stats.mtu

        return network_info
    except Exception as e:
        return {'error': str(e)}

def main():
    print("Network Interface Information:")
    print("=" * 50)

    network_info = get_network_interfaces()

    if 'error' in network_info:
        print(f"Error getting network info: {network_info['error']}")
        return

    # Print information for each interface
    for interface_name, info in network_info.items():
        print(f"\nInterface: {interface_name}")
        print(f"Status: {info['status']}")
        if 'speed' in info:
            print(f"Speed: {info['speed']} Mbps")
        if 'mtu' in info:
