#!/usr/bin/env python3

import socket
import os

def get_network_info():
    """Get basic network information"""
    info = []

    # Get hostname
    try:
        hostname = socket.gethostname()
        info.append(f"Hostname: {hostname}")
    except Exception as e:
        info.append(f"Hostname: Error - {e}")

    # Get IP address
    try:
        ip_address = socket.gethostbyname(hostname)
        info.append(f"IP Address: {ip_address}")
    except Exception as e:
        info.append(f"IP Address: Error - {e}")

    # Try to get all IP addresses
    try:
        import netifaces
        info.append("\nNetwork Interfaces (using netifaces):")
        for interface in netifaces.interfaces():
            info.append(f"  Interface: {interface}")
            addresses = netifaces.ifaddresses(interface)
            for addr_family in addresses:
                for addr in addresses[addr_family]:
                    if 'addr' in addr:
                        info.append(f"    Address: {addr['addr']}")
    except ImportError:
        info.append("\nDetailed interface information not available (netifaces module not installed)")

    return "\n".join(info)

def main():
    print("Gathering network information...")
    network_info = get_network_info()

    # Display information
    print(network_info)

    # Save to file
    try:
        with open('/workspace/network_info.txt', 'w') as f:
            f.write("Network Interface Information\n")
            f.write("=" * 40 + "\n")
            f.write(network_info)
